      const shareJson = await shareRes.json();
      expect(shareJson.sharesCount).toBeGreaterThanOrEqual(1);
      expect(shareJson.sharePath).toBe(`/posts/${postId}`);

      // 匿名访客通过分享 URL /posts/:id 直接跳转并展示动态详情，同时点击数继续递增
      const viewsBeforeShareJump = afterViewsJson.post.viewsCount as number;
      const anonPage = await anonCtx.newPage();
      const anonErrors: string[] = [];
      anonPage.on('pageerror', (err) => anonErrors.push(err.message));
      await anonPage.setViewportSize({ width: 1280, height: 800 });
      await anonPage.goto(`/posts/${postId}`);
      await expect(anonPage.getByText(title1).first()).toBeVisible({ timeout: 10000 });
      await expect(anonPage.getByText(content1).first()).toBeVisible({ timeout: 10000 });
      await expect
        .poll(async () => (await (await page.request.get(`/api/posts/${postId}`)).json()).post.viewsCount)
        .toBeGreaterThan(viewsBeforeShareJump);

      // 访问不存在的分享 URL 应优雅展示错误提示且无 JS 崩溃
      await anonPage.goto('/posts/non-existent-share-id');
      await expect(anonPage.getByText(/不存在|无法加载|未找到|已删除/i).first()).toBeVisible({ timeout: 10000 });
      expect(anonErrors, '直达有效及无效分享链接均不应触发前端异常').toEqual([]);
      await anonPage.close();

      // 进入个人主页 UI 核对「收藏」标签页展示
      const sidebar = page.locator('aside').first();
      await sidebar
        .getByRole('button', { name: /主页/ })
        .or(sidebar.getByRole('link', { name: /主页/ }))
        .first()
        .click();
      const bookmarksTab = page
        .getByRole('tab', { name: /收藏/ })
        .or(page.getByRole('button', { name: /收藏/ }))
        .first();
      await expect(bookmarksTab).toBeVisible({ timeout: 10000 });
      await bookmarksTab.click();
      await expect(page.getByText(title1).first()).toBeVisible({ timeout: 10000 });

      // 删帖级联清理：删除后收藏列表不再残留且详情返回 404
      expect((await page.request.delete(`/api/posts/${postId}`)).status()).toBe(200);
      expect((await page.request.get(`/api/posts/${postId}`)).status()).toBe(404);
      const bookmarksAfterDel = await (await page.request.get(`/api/users/${userA.id}/activity?tab=bookmarks`)).json();
      expect(bookmarksAfterDel.items.some((p: { id: string }) => p.id === postId)).toBe(false);
      expect(pageErrors).toEqual([]);
    } finally {
      await ctxB.close();
      await anonCtx.close();
    }
  });

  test('2. 右侧导航（热门话题、推荐关注）接口契约、隐私脱敏、三栏几何布局与交互闭环', async ({ page, browser }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (err) => pageErrors.push(err.message));
    await page.setViewportSize({ width: 1440, height: 900 });

    const ctxCreator = await browser.newContext();
    try {
      const creatorEmail = makeEmail('discover-creator');
      const creatorNick = `活跃达人${Date.now().toString().slice(-4)}`;
      const creator = await loginUser(ctxCreator.request, creatorEmail, creatorNick);

      const hotTag = `趋势热词${Date.now().toString().slice(-4)}`;
      const otherTag = `普通标签${Date.now().toString().slice(-4)}`;
      const hotPostTitle = `热词精选帖子-${Date.now()}`;
      const otherPostTitle = `其他分类帖子-${Date.now()}`;

      // 发布多篇带热词标签的动态提升其热度排名
      for (let i = 0; i < 3; i += 1) {
        const res = await ctxCreator.request.post('/api/posts', {
          data: {
            title: i === 0 ? hotPostTitle : `${hotPostTitle}-${i}`,
            content: '测试热门话题实时聚合排序', 
            tags: [hotTag],
          },
        });
        expect(res.status()).toBe(201);
      }
      await ctxCreator.request.post('/api/posts', {
        data: { title: otherPostTitle, content: '用于验证点击热门话题筛选隔离', tags: [otherTag] },
      });

      const viewer = await loginUser(page.request, makeEmail('discover-viewer'), '探索用户');

      // 发现接口参数边界与隐私脱敏审计
      expect((await page.request.get('/api/discover/topics?limit=0')).status()).toBe(400);
      expect((await page.request.get('/api/discover/topics?limit=99')).status()).toBe(400);
      expect((await page.request.get('/api/discover/recommended-users?limit=0')).status()).toBe(400);
      expect((await page.request.get('/api/discover/recommended-users?limit=99')).status()).toBe(400);

      const topicsJson = await (await page.request.get('/api/discover/topics?limit=10')).json();
      expect(Array.isArray(topicsJson.topics)).toBe(true);
      expect(topicsJson.topics.some((t: { tag: string }) => t.tag === hotTag)).toBe(true);

      const recRes = await page.request.get('/api/discover/recommended-users?limit=10');
      expect(recRes.status()).toBe(200);
      const recRawText = await recRes.text();
      expect(recRawText, '推荐关注接口严禁泄露任何用户邮箱').not.toContain(creatorEmail);
      const recJson = JSON.parse(recRawText);
      expect(recJson.users.some((u: { id: string }) => u.id === viewer.id), '推荐关注不应包含当前登录用户本人').toBe(false);
      expect(recJson.users.some((u: { id: string }) => u.id === creator.id)).toBe(true);

      // 浏览器 1440px 宽屏验证三栏几何布局：左导航 < 居中列表 < 右侧发现栏
