      await expect(leftSidebar).toBeVisible({ timeout: 10000 });
      await expect(feedArticle).toBeVisible({ timeout: 10000 });
      await expect(trendingTitle).toBeVisible({ timeout: 10000 });
      await expect(recTitle).toBeVisible({ timeout: 10000 });

      const leftBox = await leftSidebar.boundingBox();
      const articleBox = await feedArticle.boundingBox();
      const trendingBox = await trendingTitle.boundingBox();
      expect(leftBox && articleBox && trendingBox).toBeTruthy();
      if (leftBox && articleBox && trendingBox) {
        expect(leftBox.x + leftBox.width, '左侧导航栏应位于动态列表左侧').toBeLessThanOrEqual(articleBox.x + 24);
        expect(trendingBox.x, '右侧热门话题模块应位于动态列表右侧').toBeGreaterThanOrEqual(
