  test('3. 多账号安全切换、防越权接管、UI 身份状态同步、添加账号与分级退出闭环', async ({ page, browser }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (err) => pageErrors.push(err.message));
    await page.setViewportSize({ width: 1440, height: 900 });

    const ctxOther = await browser.newContext();
    const anonCtx = await browser.newContext();
    try {
      // 未登录切换账号必须返回 401
      expect((await anonCtx.request.post('/api/auth/switch', { data: { userId: 'any-id' } })).status()).toBe(401);

      // 独立浏览器上下文中的第三方账号 C（从未在 page 上下文登录）
      const userC = await loginUser(ctxOther.request, makeEmail('multi-victim-c'), '外部账号C');

      const nickA = `多账号甲${Date.now().toString().slice(-4)}`;
      const nickB = `多账号乙${Date.now().toString().slice(-4)}`;
      const userA = await loginUser(page.request, makeEmail('multi-a'), nickA);

      // 账号 A 发布并收藏一篇动态，用于验证切换账号后前端收藏态同步
      const sharedTitle = `身份态同步验证帖-${Date.now()}`;
      const postId = (
        await (
          await page.request.post('/api/posts', {
            data: { title: sharedTitle, content: '仅账号A收藏，切换至账号B应显示未收藏' },
          })
        ).json()
      ).post.id as string;
      expect((await page.request.post(`/api/posts/${postId}/bookmark`)).status()).toBe(200);

      // 在同一浏览器上下文登录第二个账号 B
      const userB = await loginUser(page.request, makeEmail('multi-b'), nickB);

      // 参数边界与安全隔离（防跨用户越权接管）：空 userId 返回 400，未托管的外部账号 C 返回 403
      expect((await page.request.post('/api/auth/switch', { data: { userId: '' } })).status()).toBe(400);
      expect(
        (await page.request.post('/api/auth/switch', { data: { userId: userC.id } })).status(),
        '严禁切换至未在当前浏览器验证过的外部账号'
      ).toBe(403);

      const accListJson = await (await page.request.get('/api/auth/accounts')).json();
      expect(accListJson.activeUserId).toBe(userB.id);
      expect(accListJson.accounts.some((a: { id: string }) => a.id === userA.id)).toBe(true);
      expect(accListJson.accounts.some((a: { id: string }) => a.id === userB.id)).toBe(true);

      // 账号 B 视角下该动态未收藏
      const postAsB = await (await page.request.get(`/api/posts/${postId}`)).json();
      expect(postAsB.post.bookmarkedByMe).toBe(false);

      // 浏览器 UI 验证：当前为账号 B，打开左下角账号菜单一键切换至账号 A
      await page.goto('/');
      const sidebar = page.locator('aside').first();
      const triggerB = sidebar
        .getByRole('button', { name: new RegExp(`${nickB}|个人资料|账号`, 'i') })
        .last();
      await expect(triggerB).toBeVisible({ timeout: 10000 });
      await triggerB.click();

      const switchToA = page
        .getByRole('menuitem', { name: new RegExp(nickA) })
        .or(page.getByRole('button', { name: new RegExp(nickA) }))
        .first();
      await expect(switchToA).toBeVisible({ timeout: 10000 });

      const switchPromise = page.waitForResponse(
        (r) => r.url().includes('/api/auth/switch') && r.request().method() === 'POST'
      );
      await switchToA.click();
      expect((await switchPromise).status()).toBe(200);

      // 验证激活身份已变为账号 A，且接口与页面数据均已同步为 A 视角
      const meAsA = await (await page.request.get('/api/auth/me')).json();
      expect(meAsA.user.id).toBe(userA.id);
      const postAsA = await (await page.request.get(`/api/posts/${postId}`)).json();
      expect(postAsA.post.bookmarkedByMe).toBe(true);
      await expect(sidebar.getByText(nickA).first()).toBeVisible({ timeout: 10000 });

      // 通过左下角账号菜单「添加其他账号」UI 流程再新增第三个账号 D
      const triggerA = sidebar
        .getByRole('button', { name: new RegExp(`${nickA}|个人资料|账号`, 'i') })
        .last();
      await triggerA.click();
      const addAccountBtn = page
        .getByRole('menuitem', { name: /添加.*账号/i })
        .or(page.getByRole('button', { name: /添加.*账号/i }))
        .first();
      await expect(addAccountBtn).toBeVisible({ timeout: 10000 });
      await addAccountBtn.click();

      const emailD = makeEmail('multi-d');
      const nickD = `新加丙${Date.now().toString().slice(-4)}`;
      const emailInput = page
        .getByPlaceholder(/邮箱|email/i)
        .or(page.locator('input[type="email"]'))
        .first();
      await expect(emailInput).toBeVisible({ timeout: 10000 });
      await emailInput.fill(emailD);

      const sendDPromise = page.waitForResponse(
        (r) => r.url().includes('/api/auth/send-code') && r.request().method() === 'POST'
      );
      await page.getByRole('button', { name: /获取验证码|发送验证码/i }).first().click();
      const sendDJson = await (await sendDPromise).json();
      expect(sendDJson.devCode).toMatch(/^\d{6}$/);

      await page
        .getByPlaceholder(/验证码|code/i)
        .or(page.locator('input[inputmode="numeric"]'))
        .first()
        .fill(sendDJson.devCode);
      const nickInput = page.getByPlaceholder(/昵称/i).first();
      if (await nickInput.isVisible().catch(() => false)) {
        await nickInput.fill(nickD);
      }
      const verifyDPromise = page.waitForResponse(
        (r) => r.url().includes('/api/auth/verify-code') && r.request().method() === 'POST'
      );
      await page
        .getByRole('button', { name: /验证并登录|确认登录|登录/i })
        .filter({ hasNotText: /获取验证码|发送验证码/i })
        .first()
        .click();
      expect((await verifyDPromise).status()).toBe(200);

      const meAsD = await (await page.request.get('/api/auth/me')).json();
      expect(meAsD.user.email).toBe(emailD);
      const userDId = meAsD.user.id as string;

      // 退出当前账号 D -> 自动切回剩余账号，且严禁再次切回已注销的账号 D
      const logoutOneRes = await page.request.post('/api/auth/logout', { data: {} });
      expect(logoutOneRes.status()).toBe(200);
      const meAfterOne = await (await page.request.get('/api/auth/me')).json();
      expect(meAfterOne.authenticated).toBe(true);
      expect(meAfterOne.user.id).not.toBe(userDId);

      const switchRevokedRes = await page.request.post('/api/auth/switch', { data: { userId: userDId } });
      expect(switchRevokedRes.status(), '已退出注销的账号严禁再次切回').toBe(403);

      // 一键退出全部账号 -> 所有托管账号清空，恢复未登录态
      const logoutAllRes = await page.request.post('/api/auth/logout', { data: { all: true } });
      expect(logoutAllRes.status()).toBe(200);
      const meAfterAll = await (await page.request.get('/api/auth/me')).json();
      expect(meAfterAll.authenticated).toBe(false);
      const accAfterAll = await (await page.request.get('/api/auth/accounts')).json();
      expect(accAfterAll.accounts).toEqual([]);
      expect(pageErrors).toEqual([]);
    } finally {
      await ctxOther.close();
      await anonCtx.close();
    }
  });
});

