  test('2. 通知模块全链路 API 契约、防自发、参数边界、跨用户隔离与删帖清理', async ({ page, browser }) => {
    const ctxB = await browser.newContext();
    const ctxC = await browser.newContext();
    const anonCtx = await browser.newContext();
    try {
      // 未登录访问通知与汇总未读接口必须返回 401
      expect((await anonCtx.request.get('/api/notifications')).status()).toBe(401);
      expect((await anonCtx.request.get('/api/notifications/unread-count')).status()).toBe(401);
      expect((await anonCtx.request.post('/api/notifications/read', { data: { all: true } })).status()).toBe(401);

      const userA = await loginUser(page.request, makeEmail('notif-a'), '创作者小光');
      const userB = await loginUser(ctxB.request, makeEmail('notif-b'), '互动好友小雨');
      await loginUser(ctxC.request, makeEmail('notif-c'), '无关旁观者小风');

      // 非法参数与空请求体边界校验
      expect((await page.request.get('/api/notifications?type=invalid')).status()).toBe(400);
      expect((await page.request.get('/api/notifications?limit=0')).status()).toBe(400);
      expect((await page.request.get('/api/notifications?limit=100')).status()).toBe(400);
      expect((await page.request.get('/api/notifications?offset=-1')).status()).toBe(400);
      expect((await page.request.post('/api/notifications/read', { data: {} })).status()).toBe(400);
      expect((await page.request.post('/api/notifications/read', { data: { ids: [] } })).status()).toBe(400);

      // 用户 A 发布一篇帖子，并对自己帖子点赞和评论 -> 不应产生任何自发通知
      const postTitle = `通知校验图文-${Date.now()}`;
      const postRes = await page.request.post('/api/posts', {
        data: { title: postTitle, content: '测试评论、点赞与关注通知闭环' },
      });
      expect(postRes.status()).toBe(201);
      const postId = (await postRes.json()).post.id;

      expect((await page.request.post(`/api/posts/${postId}/like`)).status()).toBe(200);
      expect(
        (await page.request.post(`/api/posts/${postId}/comments`, { data: { content: '作者自评' } })).status()
      ).toBe(201);

      const selfNotifJson = await (await page.request.get('/api/notifications')).json();
      expect(selfNotifJson.unreadCount, '本人点赞与评论自身帖子不得生成自发通知').toBe(0);
      expect(selfNotifJson.notifications.length).toBe(0);

      // 用户 B 对用户 A 执行：关注、点赞、评论
      expect((await ctxB.request.post(`/api/users/${userA.id}/follow`)).status()).toBe(200);
      expect((await ctxB.request.post(`/api/posts/${postId}/like`)).status()).toBe(200);
      const bComment = `来自好友的精彩评论-${Date.now()}`;
      const bCommentRes = await ctxB.request.post(`/api/posts/${postId}/comments`, {
        data: { content: bComment },
      });
      expect(bCommentRes.status()).toBe(201);

      // 验证全部通知列表包含 comment、like、follow 三类且未读数 >= 3
      const allNotifRes = await page.request.get('/api/notifications?type=all');
      expect(allNotifRes.status()).toBe(200);
      const allNotif = await allNotifRes.json();
      expect(allNotif.unreadCount).toBeGreaterThanOrEqual(3);
      const types = new Set(allNotif.notifications.map((n: { type: string }) => n.type));
      expect(types.has('comment')).toBe(true);
      expect(types.has('like')).toBe(true);
      expect(types.has('follow')).toBe(true);

      // 验证按分类筛选准确返回对应类型
      for (const filterType of ['comment', 'like', 'follow'] as const) {
        const filteredRes = await page.request.get(`/api/notifications?type=${filterType}`);
        expect(filteredRes.status()).toBe(200);
        const filtered = await filteredRes.json();
        expect(filtered.notifications.length).toBeGreaterThanOrEqual(1);
        expect(
          filtered.notifications.every((n: { type: string }) => n.type === filterType),
          `type=${filterType} 筛选结果不得混入其他类型`
        ).toBe(true);
      }

      // 汇总未读计数校验
      const unreadSummary = await (await page.request.get('/api/notifications/unread-count')).json();
      expect(unreadSummary.notificationsUnread).toBe(allNotif.unreadCount);

      // 跨用户安全隔离（IDOR 防护）：用户 C 不可读取且不可标记用户 A 的通知为已读
      const notifC = await (await ctxC.request.get('/api/notifications')).json();
      expect(JSON.stringify(notifC)).not.toContain(bComment);
      const firstNotifIdA = allNotif.notifications[0].id as string;
      await ctxC.request.post('/api/notifications/read', { data: { ids: [firstNotifIdA] } });
      const afterIdorAttempt = await (await page.request.get('/api/notifications')).json();
      const targetStillUnread = afterIdorAttempt.notifications.find(
        (n: { id: string; isRead: boolean }) => n.id === firstNotifIdA
      );
      expect(targetStillUnread?.isRead, '他人越权标记已读不得影响目标用户通知状态').toBe(false);

      // 用户 A 单条标为已读 -> 再一键全部标为已读
      const readOneRes = await page.request.post('/api/notifications/read', {
        data: { ids: [firstNotifIdA] },
      });
      expect(readOneRes.status()).toBe(200);
      const readOneJson = await readOneRes.json();
      expect(readOneJson.unreadCount).toBe(allNotif.unreadCount - 1);

      const readAllRes = await page.request.post('/api/notifications/read', { data: { all: true } });
      expect(readAllRes.status()).toBe(200);
      expect((await readAllRes.json()).unreadCount).toBe(0);

      // 删帖后关联通知应被清理且列表查询正常
      expect((await page.request.delete(`/api/posts/${postId}`)).status()).toBe(200);
      const afterDeleteNotifRes = await page.request.get('/api/notifications');
