      const afterDeleteNotif = await afterDeleteNotifRes.json();
      expect(
        afterDeleteNotif.notifications.some((n: { post?: { id: string } | null }) => n.post?.id === postId),
        '删除帖子后不应残留指向已删除帖子的通知'
      ).toBe(false);
    } finally {
      await ctxB.close();
      await ctxC.close();
      await anonCtx.close();
    }
  });

  test('3. WebSocket 握手安全边界、通知实时推送与零 HTTP 轮询网络审计', async ({ page, browser }) => {
    await page.setViewportSize({ width: 1280, height: 800 });
    const ctxB = await browser.newContext();
    const anonCtx = await browser.newContext();
    try {
      // 未登录请求 /api/ws 必须返回 401
      const anonWsRes = await anonCtx.request.get('/api/ws');
      expect(anonWsRes.status(), '未登录访问 /api/ws 必须返回 401').toBe(401);

      const userA = await loginUser(page.request, makeEmail('ws-notif-a'), '实时接收者A');
      await loginUser(ctxB.request, makeEmail('ws-notif-b'), '实时触发者B');

      // 已登录但未携带 Upgrade: websocket 头应返回 426（或 400）
      const nonUpgradeRes = await page.request.get('/api/ws');
      expect([400, 426]).toContain(nonUpgradeRes.status());

      // 伪造跨站 Origin 尝试握手应被 403（或 426）拒绝
      const crossOriginRes = await page.request.get('/api/ws', {
        headers: { Origin: 'https://evil-attacker.example' },
      });
      expect([403, 426]).toContain(crossOriginRes.status());

      const postRes = await page.request.post('/api/posts', {
        data: { title: `WS推送测试帖-${Date.now()}`, content: '验证无需轮询实时推送' },
      });
      const postId = (await postRes.json()).post.id;

      // 在加载页面前监听浏览器建立的 /api/ws 连接
      const wsPromise = page.waitForEvent('websocket', (ws) => ws.url().includes('/api/ws'));
      await page.goto('/');
      const ws = await wsPromise;
      expect(ws.url()).toContain('/api/ws');

      // 首屏初始化稳定后，开启 7 秒静置期网络审计（超过旧版 5 秒轮询周期），断言零轮询
      await page.waitForTimeout(1500);
      const polledUrls: string[] = [];
      const onRequest = (req: { url: () => string; method: () => string }) => {
        const u = req.url();
        if (
          req.method() === 'GET' &&
          (u.includes('/api/messages/') || u.includes('/api/notifications'))
        ) {
          polledUrls.push(u);
        }
      };
      page.on('request', onRequest);
      await page.waitForTimeout(7000);
      page.off('request', onRequest);
      expect(polledUrls, '静置期间严禁对通知或私信接口发起 HTTP 轮询').toEqual([]);

      // 进入通知页，在不刷新页面的前提下由用户 B 触发新评论与新关注，断言页面实时渲染
      const sidebar = page.locator('aside').first();
      const notifNav = sidebar
        .getByRole('button', { name: /通知/ })
        .or(sidebar.getByRole('link', { name: /通知/ }))
        .first();
      await notifNav.click();

      const liveComment = `WS实时评论推送-${Date.now()}`;
      expect((await ctxB.request.post(`/api/users/${userA.id}/follow`)).status()).toBe(200);
      expect(
        (await ctxB.request.post(`/api/posts/${postId}/comments`, { data: { content: liveComment } })).status()
      ).toBe(201);

      // 严禁 reload：直接断言新通知通过 WebSocket 实时呈现在页面上
      await expect(page.getByText(liveComment).first()).toBeVisible({ timeout: 10000 });
      await expect(page.getByText('实时触发者B').first()).toBeVisible({ timeout: 10000 });

      // 点击一键全部标为已读并验证生效
      const markAllBtn = page.getByRole('button', { name: /全部标为已读|全部已读|清空未读/i }).first();
      if (await markAllBtn.isVisible().catch(() => false)) {
        await markAllBtn.click();
        await expect
          .poll(async () => (await (await page.request.get('/api/notifications/unread-count')).json()).notificationsUnread)
          .toBe(0);
      }
    } finally {
      await ctxB.close();
      await anonCtx.close();
    }
  });

