      expect((await page.request.post(`/api/messages/with/${userA.id}/read`)).status()).toBe(400);
      expect((await page.request.post('/api/messages/with/non-existent-peer/read')).status()).toBe(404);

      // 先建立一条初始私信，使会话出现在列表中
      const firstMsg = `开场问候-${Date.now()}`;
      expect(
        (await ctxB.request.post(`/api/messages/with/${userA.id}`, { data: { content: firstMsg } })).status()
      ).toBe(201);

      const wsPromise = page.waitForEvent('websocket', (ws) => ws.url().includes('/api/ws'));
      await page.goto('/');
      await wsPromise;

      const sidebar = page.locator('aside').first();
      const dmNav = sidebar
        .getByRole('button', { name: /私信/ })
        .or(sidebar.getByRole('link', { name: /私信/ }))
        .first();
      await dmNav.click();

      const peerItem = page.getByText(userB.nickname).first();
      await expect(peerItem).toBeVisible({ timeout: 10000 });
      await peerItem.click();
      await expect(page.getByText(firstMsg).first()).toBeVisible({ timeout: 10000 });

      // 聊天窗打开稳定后审计 7 秒内零 HTTP 轮询请求
      await page.waitForTimeout(1500);
      const dmPolled: string[] = [];
      const onDmReq = (req: { url: () => string; method: () => string }) => {
        if (req.method() === 'GET' && req.url().includes('/api/messages/')) {
          dmPolled.push(req.url());
        }
      };
