      .getByRole('button', { name: /确认裁剪|应用裁剪|保存裁剪|确认|完成/i })
      .last();
    await expect(confirmCropBtn).toBeVisible({ timeout: 10000 });
    await confirmCropBtn.click();

    // 裁剪完成后填写标题与正文并发布，校验上传与帖子创建成功
    const postTitle = `裁剪构图发布-${Date.now()}`;
