  test('2. 个人主页资料修改、安全边界、关注粉丝与评论二级回复闭环', async ({ page, browser }) => {
    await page.setViewportSize({ width: 1280, height: 800 });
    const ctxB = await browser.newContext();
    const anonCtx = await browser.newContext();
    try {
      const emailA = makeEmail('social-a');
      const emailB = makeEmail('social-b');
      const userA = await loginUser(page.request, emailA, '星光作者');
      const userB = await loginUser(ctxB.request, emailB, '漫游旅人');

      // 未登录修改资料、关注、发回复必须返回 401
      expect(
        (await anonCtx.request.patch('/api/auth/profile', { data: { bio: 'unauth' } })).status()
      ).toBe(401);
      expect((await anonCtx.request.post(`/api/users/${userB.id}/follow`)).status()).toBe(401);

      // 非法 avatarUrl 协议（XSS 注入）与超长简介应被 400 拦截
      const xssAvatar = await page.request.patch('/api/auth/profile', {
        data: { avatarUrl: 'javascript:alert(1)' },
      });
      expect(xssAvatar.status()).toBe(400);

      const longBio = await page.request.patch('/api/auth/profile', {
        data: { bio: '简'.repeat(205) },
      });
      expect(longBio.status()).toBe(400);

      // 上传合法头像并更新个人简介与昵称
      const avatarUpload = await page.request.post('/api/uploads', {
        multipart: {
          file: { name: 'avatar.png', mimeType: 'image/png', buffer: PNG_32X32 },
        },
      });
      expect(avatarUpload.status()).toBe(201);
      const { url: avatarUrl } = await avatarUpload.json();

      const newNick = `星光新名${Date.now().toString().slice(-4)}`;
      const newBio = '记录城市光影、手冲咖啡与胶片日常。';
      const updateRes = await page.request.patch('/api/auth/profile', {
        data: { nickname: newNick, bio: newBio, avatarUrl },
      });
      expect(updateRes.status()).toBe(200);
      const updateJson = await updateRes.json();
      expect(updateJson.user.bio).toBe(newBio);
      expect(updateJson.user.avatarUrl).toBe(avatarUrl);

      // 隐私边界：用户 B 访问用户 A 的公开主页时，响应中严禁泄露用户 A 的 email
      const publicProfileRes = await ctxB.request.get(`/api/users/${userA.id}`);
      expect(publicProfileRes.status()).toBe(200);
      const publicProfileText = await publicProfileRes.text();
      expect(publicProfileText, '他人主页公开接口不得泄露邮箱').not.toContain(emailA);
      const publicProfileJson = JSON.parse(publicProfileText);
      expect(publicProfileJson.user.nickname).toBe(newNick);
      expect(publicProfileJson.user.bio).toBe(newBio);
      expect(publicProfileJson.user.avatarUrl).toBe(avatarUrl);

      // 禁止关注自己，关注不存在用户返回 404
      const selfFollow = await page.request.post(`/api/users/${userA.id}/follow`);
      expect(selfFollow.status()).toBe(400);
