      const followingList = await (await page.request.get(`/api/users/${userA.id}/follows?type=following`)).json();
      expect(followingList.total).toBe(1);
      expect(followingList.users.some((u: { id: string }) => u.id === userB.id)).toBe(true);

      const followersList = await (await page.request.get(`/api/users/${userB.id}/follows?type=followers`)).json();
