import { test, expect, type APIRequestContext } from '@playwright/test';

const TINY_PNG = Buffer.from(
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==',
  'base64'
);

function makeEmail(prefix: string): string {
  const rand = Math.random().toString(36).slice(2, 7);
  return `${prefix}-${Date.now()}-${rand}@example.com`;
}

async function apiLoginWithOtp(request: APIRequestContext, email: string): Promise<string> {
  const sendRes = await request.post('/api/auth/send-code', { data: { email } });
  expect(sendRes.status(), 'send-code 应返回 200').toBe(200);
  const sendJson = await sendRes.json();
  expect(sendJson.ok).toBe(true);
  expect(typeof sendJson.devCode).toBe('string');
  expect(sendJson.devCode).toMatch(/^\d{6}$/);

  const verifyRes = await request.post('/api/auth/verify-code', {
    data: { email, code: sendJson.devCode },
  });
  expect(verifyRes.status(), 'verify-code 应返回 200').toBe(200);
  const verifyJson = await verifyRes.json();
  expect(verifyJson.ok).toBe(true);
  return sendJson.devCode;
}

test.describe.serial('图文文字社区全链路加固盲测 E2E 套件', () => {
  test('1. 健康检查、首页渲染与隐藏路由 /admin 入口审计', async ({ page, request }) => {
    const pageErrors: string[] = [];
    page.on('pageerror', (err) => pageErrors.push(err.message));

    const healthRes = await request.get('/api/health');
    expect(healthRes.status()).toBe(200);
    const healthJson = await healthRes.json();
    expect(healthJson.ok).toBe(true);

    await page.goto('/');
    await expect(page.locator('body')).toBeVisible();
    // 确认公开社区页面不存在指向隐藏路由 /admin 的可见或 DOM 链接
    await expect(page.locator('a[href="/admin"]')).toHaveCount(0);
    await expect(page.locator('a[href="/admin/"]')).toHaveCount(0);
    expect(pageErrors, '首页不应存在未捕获前端运行错误').toEqual([]);
  });

  test('2. 邮箱验证码登录安全边界（非法邮箱、冷却、错误码、UI 登录与防重放）', async ({ page, request }) => {
    // 非法邮箱校验
    const badEmailRes = await request.post('/api/auth/send-code', { data: { email: 'not-an-email' } });
    expect(badEmailRes.status()).toBe(400);

    const email = makeEmail('e2e-login');
    await page.goto('/');

    const openLoginBtn = page
      .getByRole('button', { name: /登录|邮箱登录|立即登录/i })
      .or(page.getByText(/登录|邮箱登录/i))
      .first();
    await expect(openLoginBtn).toBeVisible({ timeout: 10000 });
    await openLoginBtn.click();

    const emailInput = page
      .getByPlaceholder(/邮箱|email/i)
      .or(page.locator('input[type="email"]'))
      .first();
    await expect(emailInput).toBeVisible({ timeout: 10000 });
    await emailInput.fill(email);

    const sendResponsePromise = page.waitForResponse(
      (res) => res.url().includes('/api/auth/send-code') && res.request().method() === 'POST'
    );
    const sendBtn = page.getByRole('button', { name: /获取验证码|发送验证码|发送/i }).first();
    await expect(sendBtn).toBeVisible();
    await sendBtn.click();

    const sendRes = await sendResponsePromise;
    expect(sendRes.status()).toBe(200);
    const sendJson = await sendRes.json();
    expect(sendJson.devCode).toMatch(/^\d{6}$/);

    // 同邮箱立即重发应触发冷却限制 429
    const cooldownRes = await request.post('/api/auth/send-code', { data: { email } });
    expect(cooldownRes.status()).toBe(429);

    // 错误验证码应被拒绝
    const wrongCode = sendJson.devCode === '000000' ? '999999' : '000000';
    const wrongVerifyRes = await request.post('/api/auth/verify-code', {
      data: { email, code: wrongCode },
    });
    expect([400, 401]).toContain(wrongVerifyRes.status());

    // 在 UI 中输入正确验证码完成登录
    const codeInput = page
      .getByPlaceholder(/验证码|code/i)
      .or(page.locator('input[inputmode="numeric"]'))
      .first();
    await expect(codeInput).toBeVisible();
    await codeInput.fill(sendJson.devCode);

    const verifyResponsePromise = page.waitForResponse(
      (res) => res.url().includes('/api/auth/verify-code') && res.request().method() === 'POST'
    );
    const submitBtn = page
      .getByRole('button', { name: /验证并登录|确认登录|立即登录|登录/i })
      .filter({ hasNotText: /获取验证码|发送验证码/i })
      .first();
    await submitBtn.click();

    const verifyRes = await verifyResponsePromise;
    expect(verifyRes.status()).toBe(200);

    // 确认登录态生效且刷新不丢失
    const meRes = await page.request.get('/api/auth/me');
    expect(meRes.status()).toBe(200);
    const meJson = await meRes.json();
    expect(meJson.authenticated).toBe(true);
    expect(meJson.user?.email).toBe(email);

    // 同一验证码二次提交必须被拒（一次性防重放）
    const replayRes = await request.post('/api/auth/verify-code', {
      data: { email, code: sendJson.devCode },
    });
    expect([400, 401]).toContain(replayRes.status());
  });

  test('3. 图文发布、图片上传、搜索、点赞、评论与持久化闭环', async ({ page }) => {
    const email = makeEmail('e2e-poster');
    await apiLoginWithOtp(page.request, email);

    // 校验非图片文件上传被拒
    const badUploadRes = await page.request.post('/api/uploads', {
      multipart: {
        file: {
          name: 'evil.html',
          mimeType: 'text/html',
          buffer: Buffer.from('<script>alert(1)</script>'),
        },
      },
    });
    expect([400, 415]).toContain(badUploadRes.status());

    // 校验合法 PNG 上传与 nosniff 安全响应头
    const uploadRes = await page.request.post('/api/uploads', {
      multipart: {
        file: {
          name: 'photo.png',
          mimeType: 'image/png',
          buffer: TINY_PNG,
        },
      },
    });
    expect(uploadRes.status()).toBe(201);
    const uploadJson = await uploadRes.json();
    expect(uploadJson.url).toMatch(/^\/api\/uploads\//);

    const imgGetRes = await page.request.get(uploadJson.url);
    expect(imgGetRes.status()).toBe(200);
    expect(imgGetRes.headers()['content-type']).toContain('image/png');
    expect((imgGetRes.headers()['x-content-type-options'] || '').toLowerCase()).toBe('nosniff');

    // 校验恶意 javascript: imageUrl 与空标题被拦截
    const xssPostRes = await page.request.post('/api/posts', {
      data: {
        title: 'XSS测试',
        content: '测试非法图片协议拦截',
        imageUrl: 'javascript:alert(1)',
      },
    });
    expect(xssPostRes.status()).toBe(400);

    const emptyTitleRes = await page.request.post('/api/posts', {
      data: { title: '   ', content: '无标题内容' },
    });
    expect(emptyTitleRes.status()).toBe(400);

    // 通过 UI 入口打开图文发布弹窗并提交（兼容上传或填入 URL）
    const postTitle = `年轻人的周末灵感-${Date.now()}`;
    const postBody = '记录一杯冰美式和落日余晖，首版图文社区真好用！';
    const commentText = `太赞了同款机位-${Date.now()}`;

    await page.goto('/');
    const composeBtn = page
      .getByRole('button', { name: /发布图文|发布|写图文|发帖/i })
      .first();
    await expect(composeBtn).toBeVisible({ timeout: 10000 });
    await composeBtn.click();

    const titleInput = page
      .getByPlaceholder(/标题|起个标题/i)
      .or(page.getByLabel(/标题/i))
      .first();
    await expect(titleInput).toBeVisible({ timeout: 10000 });
    await titleInput.fill(postTitle);

    const contentInput = page
      .getByPlaceholder(/正文|内容|分享|此刻|想说/i)
      .or(page.locator('textarea'))
      .first();
    await expect(contentInput).toBeVisible();
    await contentInput.fill(postBody);

    const fileInput = page.locator('input[type="file"]').first();
    if ((await fileInput.count()) > 0) {
      await fileInput.setInputFiles({
        name: 'community-card.png',
        mimeType: 'image/png',
        buffer: TINY_PNG,
      });
    }

    const createPostPromise = page.waitForResponse(
      (res) => res.url().endsWith('/api/posts') && res.request().method() === 'POST'
    );
    const publishBtn = page
      .getByRole('button', { name: /立即发布|确认发布|发布帖子|提交|发布/i })
      .last();
    await publishBtn.click();

    const createPostRes = await createPostPromise;
    expect(createPostRes.status()).toBe(201);
    const createdJson = await createPostRes.json();
    const postId = createdJson.post?.id;
    expect(postId).toBeTruthy();

    // 刷新页面验证图文持久化可见
    await page.reload();
    await expect(page.getByText(postTitle).first()).toBeVisible({ timeout: 10000 });

    // 验证搜索接口命中
    const searchRes = await page.request.get(`/api/posts?q=${encodeURIComponent(postTitle)}`);
    expect(searchRes.status()).toBe(200);
    const searchJson = await searchRes.json();
    expect(searchJson.posts.some((p: { id: string }) => p.id === postId)).toBe(true);

    // 点赞切换与评论持久化校验
    const like1 = await page.request.post(`/api/posts/${postId}/like`);
    expect(like1.status()).toBe(200);
    const like1Json = await like1.json();
    expect(like1Json.liked).toBe(true);
    expect(like1Json.likesCount).toBe(1);

    const like2 = await page.request.post(`/api/posts/${postId}/like`);
    expect(like2.status()).toBe(200);
    const like2Json = await like2.json();
    expect(like2Json.liked).toBe(false);
    expect(like2Json.likesCount).toBe(0);

    const emptyComment = await page.request.post(`/api/posts/${postId}/comments`, {
      data: { content: '   ' },
    });
    expect(emptyComment.status()).toBe(400);

    const addComment = await page.request.post(`/api/posts/${postId}/comments`, {
      data: { content: commentText },
    });
    expect(addComment.status()).toBe(201);

    const detailRes = await page.request.get(`/api/posts/${postId}`);
    expect(detailRes.status()).toBe(200);
    const detailJson = await detailRes.json();
    expect(detailJson.comments.some((c: { content: string }) => c.content === commentText)).toBe(true);
  });

  test('4. 未登录拦截与跨用户越权删帖权限隔离', async ({ browser }) => {
    // 未登录请求应全部返回 401
    const anonCtx = await browser.newContext();
    const anonPost = await anonCtx.request.post('/api/posts', {
      data: { title: '未登录发帖', content: '应当被拒绝' },
    });
    expect(anonPost.status()).toBe(401);

    const anonUpload = await anonCtx.request.post('/api/uploads', {
      multipart: { file: { name: 'a.png', mimeType: 'image/png', buffer: TINY_PNG } },
    });
    expect(anonUpload.status()).toBe(401);
    await anonCtx.close();

    // 用户 A 发帖，用户 B 尝试越权删除必须返回 403，作者本人删除返回 200
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    try {
      await apiLoginWithOtp(ctxA.request, makeEmail('e2e-owner'));
      await apiLoginWithOtp(ctxB.request, makeEmail('e2e-other'));

      const created = await ctxA.request.post('/api/posts', {
        data: { title: `权限测试-${Date.now()}`, content: '仅作者可删' },
      });
      expect(created.status()).toBe(201);
      const postId = (await created.json()).post.id;

      const forbiddenDel = await ctxB.request.delete(`/api/posts/${postId}`);
      expect(forbiddenDel.status()).toBe(403);

      const ownerDel = await ctxA.request.delete(`/api/posts/${postId}`);
      expect(ownerDel.status()).toBe(200);

      const afterDel = await ctxA.request.get(`/api/posts/${postId}`);
      expect(afterDel.status()).toBe(404);
    } finally {
      await ctxA.close();
      await ctxB.close();
    }
  });

  test('5. 隐藏路由 /admin 全流程：鉴权、Resend 密钥脱敏配置、改密与状态回滚', async ({ page, browser }) => {
    const tempResendKey = 're_e2e_secret_key_987654321';
    const newAdminPwd = 'AdminNew#2026';
    let passwordChanged = false;
    let resendKeyUpdated = false;

    // 未认证访问后台敏感接口必须返回 401
    const anonCtx = await browser.newContext();
    expect((await anonCtx.request.get('/api/admin/settings')).status()).toBe(401);
    expect(
      (await anonCtx.request.put('/api/admin/settings', { data: { siteName: 'Hack' } })).status()
    ).toBe(401);
    expect(
      (
        await anonCtx.request.post('/api/admin/password', {
          data: { currentPassword: 'admin', newPassword: 'hacked123' },
        })
      ).status()
    ).toBe(401);
    await anonCtx.close();

    try {
      await page.goto('/admin');
      const pwdInput = page.locator('input[type="password"]').first();
      await expect(pwdInput).toBeVisible({ timeout: 10000 });

      // 错误密码登录失败
      const wrongLoginPromise = page.waitForResponse(
        (res) => res.url().includes('/api/admin/login') && res.request().method() === 'POST'
      );
      await pwdInput.fill('wrong-admin-pwd');
      const adminLoginBtn = page.getByRole('button', { name: /登录|进入后台|确认/i }).first();
      await adminLoginBtn.click();
      const wrongLoginRes = await wrongLoginPromise;
      expect(wrongLoginRes.status()).toBe(401);

      // 初始密码 admin 登录成功
      const okLoginPromise = page.waitForResponse(
        (res) => res.url().includes('/api/admin/login') && res.request().method() === 'POST'
      );
      await pwdInput.fill('admin');
      await adminLoginBtn.click();
      const okLoginRes = await okLoginPromise;
      expect(okLoginRes.status()).toBe(200);

      // 在后台配置 Resend API Key 并验证 GET 接口严格脱敏（绝不返回明文）
      const resendInput = page
        .getByPlaceholder(/re_|Resend|API Key|密钥/i)
        .or(page.getByLabel(/Resend|API Key|密钥/i))
        .first();
      await expect(resendInput).toBeVisible({ timeout: 10000 });
      await resendInput.fill(tempResendKey);

      const saveSettingsPromise = page.waitForResponse(
        (res) => res.url().includes('/api/admin/settings') && res.request().method() === 'PUT'
      );
      const saveBtn = page.getByRole('button', { name: /保存配置|保存设置|保存/i }).first();
      await saveBtn.click();
      const saveRes = await saveSettingsPromise;
      expect(saveRes.status()).toBe(200);
      resendKeyUpdated = true;

      const settingsGetRes = await page.request.get('/api/admin/settings');
      expect(settingsGetRes.status()).toBe(200);
      const settingsRawText = await settingsGetRes.text();
      expect(settingsRawText, 'GET /api/admin/settings 绝不得明文暴露 Resend API Key').not.toContain(
        tempResendKey
      );
      const settingsJson = JSON.parse(settingsRawText);
      expect(settingsJson.hasResendApiKey).toBe(true);
      expect(typeof settingsJson.resendApiKeyMasked).toBe('string');
      expect(settingsJson.resendApiKeyMasked.length).toBeGreaterThan(0);

      // 改密边界校验：原密码错误返回 401、新密码过短返回 400
      const badOldPwd = await page.request.post('/api/admin/password', {
        data: { currentPassword: 'not-admin', newPassword: newAdminPwd },
      });
      expect(badOldPwd.status()).toBe(401);

      const shortPwd = await page.request.post('/api/admin/password', {
        data: { currentPassword: 'admin', newPassword: '123' },
      });
      expect(shortPwd.status()).toBe(400);

      // 合法修改管理员密码，并验证旧密码失效、新密码可登录
      const changePwdRes = await page.request.post('/api/admin/password', {
        data: { currentPassword: 'admin', newPassword: newAdminPwd },
      });
      expect(changePwdRes.status()).toBe(200);
      passwordChanged = true;

      const verifyCtx = await browser.newContext();
      try {
        const oldPwdLogin = await verifyCtx.request.post('/api/admin/login', {
          data: { password: 'admin' },
        });
        expect(oldPwdLogin.status()).toBe(401);

        const newPwdLogin = await verifyCtx.request.post('/api/admin/login', {
          data: { password: newAdminPwd },
        });
        expect(newPwdLogin.status()).toBe(200);
      } finally {
        await verifyCtx.close();
      }
    } finally {
      // 严格回滚全局管理员配置，保证测试套件可重复无污染运行
      const cleanupCtx = await browser.newContext();
      try {
        const activePwd = passwordChanged ? newAdminPwd : 'admin';
        const loginRes = await cleanupCtx.request.post('/api/admin/login', {
          data: { password: activePwd },
        });
        if (loginRes.status() === 200) {
          if (resendKeyUpdated) {
            await cleanupCtx.request.put('/api/admin/settings', {
              data: { resendApiKey: '' },
            });
          }
          if (passwordChanged) {
            await cleanupCtx.request.post('/api/admin/password', {
              data: { currentPassword: newAdminPwd, newPassword: 'admin' },
            });
          }
        }
      } finally {
        await cleanupCtx.close();
      }
    }
  });
